CREATE OR ALTER PROCEDURE [dbo].[uspContract_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @ContractNumber NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @SignedDate DATETIME2 = NULL
	, @EffectiveFrom DATETIME2 = NULL
	, @EffectiveTo DATETIME2 = NULL
	, @ContractValue DECIMAL(18,4) = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, t.[StartDate]
			, t.[EndDate]
			, t.[PaymentTerm]
			, t.[Status]
			, t.[Note]
			, t.[ContractNumber]
			, t.[Name]
			, t.[SignedDate]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[ContractValue]
			, t.[CreatedDate]
		FROM [dbo].[Contract] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[ContractNumber] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@ContractNumber, '') = '' OR t.[ContractNumber] LIKE CONCAT('%', @ContractNumber, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (@SignedDate IS NULL OR t.[SignedDate] = @SignedDate)
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND (@ContractValue IS NULL OR t.[ContractValue] = @ContractValue)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'startDate' THEN r.[StartDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'startDate' THEN r.[StartDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'endDate' THEN r.[EndDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'endDate' THEN r.[EndDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'paymentTerm' THEN r.[PaymentTerm] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'paymentTerm' THEN r.[PaymentTerm] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractNumber' THEN r.[ContractNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractNumber' THEN r.[ContractNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'signedDate' THEN r.[SignedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'signedDate' THEN r.[SignedDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractValue' THEN r.[ContractValue] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractValue' THEN r.[ContractValue] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
